# PowerShell: check for ".\downloads" folder in current directory and create it if missing
if (-not (Test-Path -LiteralPath ".\downloads" -PathType Container)) {
    New-Item -Path ".\downloads" -ItemType Directory | Out-Null
    Write-Output "Created .\downloads"
} else {
    Write-Output "Folder .\downloads already exists"
}

