$paths = 'C:\Users\Docker\Downloads\input.png','C:\Users\Docker\Downloads\output_high_contrast.png'
foreach ($p in $paths) {
    if (-not (Test-Path $p)) {
        Write-Host "$p : FILE NOT FOUND"
        continue
    }
    $i = Get-Item $p
    $b = $i.Length
    if ($b -ge 1GB) { $hr = "{0:N2} GB" -f ($b/1GB) }
    elseif ($b -ge 1MB) { $hr = "{0:N2} MB" -f ($b/1MB) }
    elseif ($b -ge 1KB) { $hr = "{0:N2} KB" -f ($b/1KB) }
    else { $hr = "$b bytes" }
    Write-Host "$($i.FullName) : $b bytes ($hr)"
}

